function buildLessons(topic: Topic): Lesson[] {
  const lessonTitles: [string, string, string, string] = ['Reconocer el concepto', 'Diferenciar ideas cercanas', 'Aplicar en un caso', 'Reto de consolidación']
  return lessonTitles.map((title, lessonIndex) => {
    const facts = topic.facts; const at = (offset: number) => facts[(lessonIndex + offset) % facts.length]; const idx = (fact: Fact) => facts.indexOf(fact)
    const definition = (position: number, fact: Fact) => mc(`${topic.id}-lesson-${lessonIndex + 1}-q${position}`, `¿Qué enunciado define mejor ${fact.term.toLowerCase()}?`, facts.map((item) => item.definition), idx(fact), fact.definition, `${fact.term}: ${fact.definition}`)
    const caseQuestion = (position: number, fact: Fact) => mc(`${topic.id}-lesson-${lessonIndex + 1}-q${position}`, `¿Qué concepto se reconoce en este caso? ${fact.application}`, facts.map((item) => item.term), idx(fact), `El caso corresponde a ${fact.term.toLowerCase()}.`, `${fact.term}: ${fact.definition}`)
    const wordBank = (position: number, fact: Fact) => wb(`${topic.id}-lesson-${lessonIndex + 1}-q${position}`, `Completa: {{respuesta}} es ${fact.definition.toLowerCase()}`, facts.map((item) => item.term), idx(fact), `La definición corresponde a ${fact.term.toLowerCase()}.`, `${fact.term}: ${fact.definition}`)
    const trueFact = at(3); const falseFact = at(4)
    return { id: `${topic.id}-lesson-${lessonIndex + 1}`, title, order: lessonIndex + 1, theory: `Practica ${topic.title.toLowerCase()} de manera breve y aplicada.`, exercises: [
      definition(1, at(0)), caseQuestion(2, at(1)), wordBank(3, at(2)),
      tf(`${topic.id}-lesson-${lessonIndex + 1}-q4`, `${trueFact.term} se refiere a: ${trueFact.definition}`, true, `La afirmación describe correctamente ${trueFact.term.toLowerCase()}.`, `${trueFact.term}: ${trueFact.definition}`),
      tf(`${topic.id}-lesson-${lessonIndex + 1}-q5`, `${falseFact.term} se refiere a: ${at(0).definition}`, false, `La definición no corresponde a ${falseFact.term.toLowerCase()}.`, `${falseFact.term}: ${falseFact.definition}`),
      definition(6, at(4)), wordBank(7, at(0)),
      matching(`${topic.id}-lesson-${lessonIndex + 1}-q8`, 'Relaciona cada concepto con su idea central.', [[at(0).term, at(0).definition], [at(1).term, at(1).definition], [at(2).term, at(2).definition]], 'Cada término se distingue por su función y definición.', 'Relacionar definición y caso evita confusiones.'),
      caseQuestion(9, at(2)),
      caseQuestion(10, at(3)),
    ] }
  })
}

function createStage(id: string, title: string, subtitle: string, units: Unit[]): HumanitiesStage { return { id, title, subtitle, sections: units.map((unit) => ({ id: unit.id, title: unit.title, subtitle: unit.subtitle, icon: unit.icon, color: unit.color, nodes: unit.topics.map((topic, index) => ({ id: topic.id, title: topic.title, icon: ['💡', '📚', '🧩'][index], lessons: buildLessons(topic) })) })) } }

